 "content": "def transform(grid):
    """Encode counts of horizontal 3- and 2-colored bars in a 2x3 grid."""
    bars = {2: 0, 3: 0}
    for row in grid:
        i = 0
        while i < len(row):
            color = row[i]
            if color in bars:
                bars[color] += 1
                while i < len(row) and row[i] == color:
                    i += 1
            else:
                i += 1
    cells = [3] * bars[3] + [2] * bars[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
